    setBooking(existing);
    setTouched(NOT_TOUCHED);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [screeningId]);

  if (!booking) {
    return null;
  }

  const values = booking.formValues;
  const units = getSortedSelectedUnits(booking.seats);
  const total = getTotalPrice(units);

