// Minimal CDP driver using built-in Node WebSocket + fetch. No project deps added.
const BASE = 'http://127.0.0.1:9222';

async function newTab(url) {
  const res = await fetch(`${BASE}/json/new?${encodeURIComponent(url || 'about:blank')}`, { method: 'PUT' });
  return res.json();
}

function connect(wsUrl) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket(wsUrl);
    ws.addEventListener('open', () => resolve(ws));
    ws.addEventListener('error', (e) => reject(e));
  });
}

class Session {
  constructor(ws) {
    this.ws = ws;
    this.id = 0;
    this.pending = new Map();
    this.events = [];
    ws.addEventListener('message', (ev) => {
      const msg = JSON.parse(ev.data);
      if (msg.id && this.pending.has(msg.id)) {
        const { resolve, reject } = this.pending.get(msg.id);
        this.pending.delete(msg.id);
        if (msg.error) reject(new Error(JSON.stringify(msg.error)));
        else resolve(msg.result);
      } else if (msg.method) {
        this.events.push(msg);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
    });
  }
  async waitForEvent(method, timeoutMs = 10000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      const idx = this.events.findIndex((e) => e.method === method);
      if (idx !== -1) return this.events.splice(idx, 1)[0];
      await new Promise((r) => setTimeout(r, 100));
    }
    throw new Error(`timeout waiting for ${method}`);
  }
}

async function main() {
  const tab = await newTab('about:blank');
  const ws = await connect(tab.webSocketDebuggerUrl);
  const s = new Session(ws);
  await s.send('Page.enable');
  await s.send('Runtime.enable');
  await s.send('Network.enable');
  global.__session = s;
  global.__tab = tab;
  return { s, tab };
}

module.exports = { main, Session, connect, newTab, BASE };

