const fs = require('fs');

const SHOT_DIR = '/tmp/shots';
fs.mkdirSync(SHOT_DIR, { recursive: true });

function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

async function run() {
  const { s } = await main();

  const consoleMsgs = [];
  s.ws.addEventListener('message', (ev) => {
    const msg = JSON.parse(ev.data);
    if (msg.method === 'Runtime.consoleAPICalled') {
      const args = (msg.params.args || []).map((a) => a.value ?? a.description ?? '').join(' ');
      consoleMsgs.push(`[${msg.params.type}] ${args}`);
    }
    if (msg.method === 'Runtime.exceptionThrown') {
      consoleMsgs.push(`[exception] ${JSON.stringify(msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails)}`);
    }
  });

  async function evaluate(expression) {
    const result = await s.send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails));
    return result.result.value;
  }

  async function screenshot(name) {
    const { data } = await s.send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(`${SHOT_DIR}/${name}.png`, Buffer.from(data, 'base64'));
    console.log(`screenshot: ${name}.png`);
  }

  async function waitForSelector(sel, timeoutMs = 10000) {
    const start = Date.now();
    while (Date.now() - start < timeoutMs) {
      const found = await evaluate(`!!document.querySelector(${JSON.stringify(sel)})`);
      if (found) return true;
      await sleep(200);
    }
    throw new Error(`timeout waiting for selector ${sel}`);
  }

  async function click(sel) {
    await evaluate(`document.querySelector(${JSON.stringify(sel)}).click()`);
  }

  async function typeInto(sel, value) {
    await evaluate(`
      (function() {
        const el = document.querySelector(${JSON.stringify(sel)});
        const proto = el.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype;
        const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
        setter.call(el, ${JSON.stringify(value)});
        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('blur', { bubbles: true }));
      })();
    `);
  }

  // 1. Navigate to movie list
  await s.send('Page.navigate', { url: 'http://localhost:4200/' });
  await sleep(500);
  await waitForSelector('[data-testid="movie-list"], [data-testid="movies-empty"], [data-testid="movies-error"]', 15000);
  await screenshot('01-movie-list');
  const movieListInfo = await evaluate(`
    JSON.stringify({
      title: document.title,
      dayPicker: !!document.querySelector('[data-testid="day-picker"]'),
      movieCards: document.querySelectorAll('[data-testid="movie-card"]').length,
      screeningButtons: document.querySelectorAll('[data-testid="screening-button"]').length,
    })
  `);
  console.log('movie list:', movieListInfo);

  // 2. Click first screening button
  await click('[data-testid="screening-button"]');
  await waitForSelector('[data-testid="seat-map"]', 15000);
  await sleep(300);
  await screenshot('02-seat-map');
  const seatMapInfo = await evaluate(`
    JSON.stringify({
      seats: document.querySelectorAll('[data-testid="seat"]').length,
      couches: document.querySelectorAll('[data-testid="couch"]').length,
      title: document.querySelector('[data-testid="seat-map-title"]')?.textContent,
      subtitle: document.querySelector('[data-testid="seat-map-subtitle"]')?.textContent,
    })
  `);
  console.log('seat map:', seatMapInfo);

  // 3. Select two available seats
  const availableSeats = await evaluate(`
    Array.from(document.querySelectorAll('[data-testid="seat"][data-state="available"]')).slice(0, 2).map(el => el.outerHTML.slice(0, 80))
  `);
  console.log('available seats sample:', availableSeats);
  await evaluate(`
    Array.from(document.querySelectorAll('[data-testid="seat"][data-state="available"]')).slice(0, 2).forEach(el => el.click())
  `);
  await sleep(300);
  await screenshot('03-seats-selected');
  const selectedInfo = await evaluate(`
    JSON.stringify({
      count: document.querySelector('[data-testid="selected-seats-count"]')?.textContent,
      continueDisabled: document.querySelector('[data-testid="continue-button"]')?.disabled,
    })
  `);
  console.log('selected:', selectedInfo);

  // 4. Continue to summary
  await click('[data-testid="continue-button"]');
  await waitForSelector('[data-testid="summary-list"]', 15000);
  await sleep(300);
  await screenshot('04-summary');
  const summaryInfo = await evaluate(`
    JSON.stringify({
      items: document.querySelectorAll('[data-testid="summary-item"]').length,
      total: document.querySelector('[data-testid="summary-total"]')?.textContent,
    })
  `);
  console.log('summary:', summaryInfo);

  // 5. Confirm to checkout
  await click('[data-testid="confirm-button"]');
  await waitForSelector('[data-testid="checkout-title"]', 15000);
  await sleep(300);
  await screenshot('05-checkout-empty');

  // 6. Fill checkout form
  await typeInto('[data-testid="first-name-input"] input', 'Jane');
  await typeInto('[data-testid="last-name-input"] input', 'Doe');
  await typeInto('[data-testid="email-input"] input', 'jane.doe@example.com');
  await typeInto('[data-testid="confirm-email-input"] input', 'jane.doe@example.com');
  await typeInto('[data-testid="phone-input"] input', '123456789');
  await click('[data-testid="terms-checkbox"]');
  await sleep(200);
  await screenshot('06-checkout-filled');

  // 7. Pay
  await click('[data-testid="pay-button"]');
  await waitForSelector('[data-testid="confirmation-heading"]', 15000);
  await sleep(300);
  await screenshot('07-confirmation');
  const confirmationInfo = await evaluate(`
    JSON.stringify({
      message: document.querySelector('[data-testid="confirmation-message"]')?.textContent,
    })
  `);
  console.log('confirmation:', confirmationInfo);

  console.log('--- console messages ---');
  consoleMsgs.forEach((m) => console.log(m));

  process.exit(0);
}

run().catch((e) => {
  console.error('FLOW FAILED:', e);
  process.exit(1);
});

