// Fake "today" to 2026-09-15 so it lines up with db.json's seeded screening dates
// (this sandbox's real clock is 2026-10-20, past the fixture window). Test-only override.
await s.send('Page.addScriptToEvaluateOnNewDocument', {
  source: `
    (function() {
      const FAKE_NOW = new Date('2026-09-15T10:00:00Z').getTime();
      const OffsetDate = Date;
      const offset = FAKE_NOW - OffsetDate.now();
      class FakeDate extends OffsetDate {
        constructor(...args) {
          if (args.length === 0) super(OffsetDate.now() + offset);
          else super(...args);
        }
        static now() { return OffsetDate.now() + offset; }
      }
      window.Date = FakeDate;
    })();
  `,
});

// 1. Navigate to movie list
await s.send('Page.navigate', { url: 'http://localhost:4200/' });

